package com.oms.inventory.service.impl;
import java.util.*;
import static com.oms.inventory.service.impl.WarehouseAllocationPlanner.*;
/** Whole-kit planning uses bounded warehouse/component scans, never one iteration per purchased set. */
public final class BundleWarehousePlanner {
 private BundleWarehousePlanner(){}
 @SuppressWarnings("unchecked") public static List<Map<String,Object>> plan(List<Map<String,Object>> sources,List<Map<String,Object>> batches,List<Map<String,Object>> stores,List<Map<String,Object>> existing,long required,boolean multi,boolean partial,boolean split,Map<String,Object> policy){
  List<Map<String,Object>> lines=policy.get("lines") instanceof List?(List<Map<String,Object>>)policy.get("lines"):Collections.emptyList();Map<Long,List<Map<String,Object>>> kits=new LinkedHashMap<>();for(Map<String,Object> line:lines)if(n(line,"bundle_id")>0&&s(line,"lucky_sku").isEmpty())kits.computeIfAbsent(n(line,"bundle_id"),k->new ArrayList<>()).add(line);
  if(kits.isEmpty())return WarehouseAllocationPlanner.plan(sources,batches,stores,existing,required,multi,partial,split,policy);
  require(kits.size()<=100&&stores.size()<=100,"套装或候选仓数量超限");boolean splitKit=n(policy,"allow_bundle_split")==1,parts=n(policy,"allow_bundle_partial_components")==1;require(!splitKit||multi,"套内组件跨仓需允许多仓发货");require(!parts||partial,"组件部分发货需允许部分发货");
  WarehouseAllocationPlanner.Budget budget=new WarehouseAllocationPlanner.Budget(existing,policy,multi);budget.check(Collections.emptyList());if(quantity(existing)==required)return Collections.emptyList();State state=new State(sources,batches);List<Map<String,Object>> out=new ArrayList<>();Set<String> selected=new LinkedHashSet<>();Set<Long> kitDemands=new HashSet<>();
  for(Map.Entry<Long,List<Map<String,Object>>> group:kits.entrySet()){
   List<Map<String,Object>> components=group.getValue();require(!components.isEmpty()&&components.size()<=50,"套装组件数量无效");Set<String> identities=new HashSet<>();Map<String,Long> coefficients=new LinkedHashMap<>(),remaining=new LinkedHashMap<>();Set<String> prior=new HashSet<>();long sets=Long.MAX_VALUE;
   for(Map<String,Object> component:components){String identity=com.oms.common.util.FulfillmentLineKey.of(component);require(identities.add(identity)&&n(component,"component_quantity")>0,"套装组件身份或配比无效");coefficients.put(identity,n(component,"component_quantity"));long used=0;for(Map<String,Object> row:existing)if(identity.equals(com.oms.common.util.FulfillmentLineKey.of(row))){used+=n(row,"quantity");prior.add(s(row,"store_code"));}long left=n(component,"quantity")-n(component,"cancelled_quantity")-used;require(left>=0,"套装累计分仓超过需求");remaining.put(identity,left);sets=Math.min(sets,left/n(component,"component_quantity"));for(Map<String,Object> source:sources)if(identity.equals(com.oms.common.util.FulfillmentLineKey.of(source)))kitDemands.add(n(source,"demand_id"));}
   if(!parts)for(String identity:identities)require(remaining.get(identity)==sets*coefficients.get(identity),"套装剩余组件比例不完整，请核对已发、截单和指定组件取消范围");
   if(parts){List<Map<String,Object>> allowed=new ArrayList<>(stores);if(!splitKit){require(prior.size()<=1,"套内已有跨仓履约，不能按同仓组件规则继续");if(!prior.isEmpty())allowed.removeIf(w->!prior.contains(s(w,"store_code")));else if("FEWEST_SHIPMENTS".equals(s(policy,"strategy")))allowed.sort((a,b)->Long.compare(state.coverage(identities,s(b,"store_code")),state.coverage(identities,s(a,"store_code"))));}
    for(Map<String,Object> store:allowed){String code=s(store,"store_code");if(!budget.allows(code,selected))continue;boolean took=false;for(String identity:identities){long take=Math.min(remaining.get(identity),state.available(identity,code));if(take>0){List<Map<String,Object>> rows=state.take(identity,take,store);out.addAll(rows);remaining.put(identity,remaining.get(identity)-take);took=true;}}if(took){selected.add(code);if(!splitKit)break;}}
   }else if(!splitKit){List<Map<String,Object>> allowed=new ArrayList<>(stores);if("FEWEST_SHIPMENTS".equals(s(policy,"strategy")))allowed.sort((a,b)->Long.compare(state.sets(coefficients,s(b,"store_code")),state.sets(coefficients,s(a,"store_code"))));
    for(Map<String,Object> store:allowed){String code=s(store,"store_code");if(sets==0)break;if(!budget.allows(code,selected))continue;long take=Math.min(sets,state.sets(coefficients,code));if(take==0)continue;for(String identity:identities)out.addAll(state.take(identity,Math.multiplyExact(take,coefficients.get(identity)),store));selected.add(code);sets-=take;}
   }else{
    long upper=sets;for(String identity:identities){long cap=0;for(Map<String,Object> store:stores)cap+=state.available(identity,s(store,"store_code"));upper=Math.min(upper,cap/coefficients.get(identity));}
    // Binary search only the number of complete sets; each trial is a bounded source/batch scan.
    long low=0,high=upper;State best=null;List<Map<String,Object>> bestRows=Collections.emptyList();while(low<=high){long mid=low+(high-low)/2;if(mid==0){low=1;continue;}State trial=new State(state);List<Map<String,Object>> rows=new ArrayList<>();Set<String> chosen=new LinkedHashSet<>(selected);boolean ok=true;for(String identity:identities){long left=Math.multiplyExact(mid,coefficients.get(identity));for(Map<String,Object> store:stores){String code=s(store,"store_code");if(!budget.allows(code,chosen))continue;long take=Math.min(left,trial.available(identity,code));if(take>0){rows.addAll(trial.take(identity,take,store));chosen.add(code);left-=take;}if(left==0)break;}if(left>0){ok=false;break;}}if(ok){best=trial;bestRows=rows;low=mid+1;}else high=mid-1;}
    if(best!=null){state.sources.clear();state.sources.addAll(best.sources);state.batches.clear();state.batches.addAll(best.batches);out.addAll(bestRows);for(Map<String,Object> row:bestRows)selected.add(s(row,"store_code"));}
   }
  }
  List<Map<String,Object>> ordinary=new ArrayList<>(),oldOrdinary=new ArrayList<>();for(Map<String,Object> row:state.sources)if((n(row,"bundle_id")==0||!s(row,"lucky_sku").isEmpty())&&n(row,"quantity")>0)ordinary.add(row);for(Map<String,Object> row:existing)if(!kitDemands.contains(n(row,"demand_id"))&&!belongs(row,kits))oldOrdinary.add(row);
  if(!ordinary.isEmpty()){Map<String,Object> p=new LinkedHashMap<>(policy);p.put("min_first_allocation_percent",0);p.put("planned_stores",selected);List<Map<String,Object>> inherited=new ArrayList<>();if(policy.get("global_fulfillment") instanceof List)inherited.addAll((List<Map<String,Object>>)policy.get("global_fulfillment"));inherited.addAll(existing);inherited.addAll(out);p.put("global_fulfillment",inherited);try{out.addAll(WarehouseAllocationPlanner.plan(ordinary,state.batches,stores,oldOrdinary,quantity(ordinary)+quantity(oldOrdinary),multi,partial,split,p));}catch(IllegalArgumentException e){if(!partial)throw e;}}
  long planned=quantity(out),occupied=quantity(existing);require(planned>0&&(partial||occupied+planned==required),"当前仓库无法满足完整套装；请补齐组件库存或核对套装拆分规则");long percent=n(policy,"min_first_allocation_percent");require(occupied>0||planned>=java.math.BigDecimal.valueOf(required).multiply(java.math.BigDecimal.valueOf(percent)).divide(java.math.BigDecimal.valueOf(100),0,java.math.RoundingMode.CEILING).longValueExact(),"套装方案未达到首次最低满足比例");budget.check(out);return out;
 }
 private static boolean belongs(Map<String,Object> row,Map<Long,List<Map<String,Object>>> kits){String key=com.oms.common.util.FulfillmentLineKey.of(row);for(List<Map<String,Object>> components:kits.values())for(Map<String,Object> c:components)if(key.equals(com.oms.common.util.FulfillmentLineKey.of(c)))return true;return false;}
 private static final class State {
  final List<Map<String,Object>> sources=new ArrayList<>(),batches=new ArrayList<>();
  State(List<Map<String,Object>> source,List<Map<String,Object>> batch){for(Map<String,Object> row:source)sources.add(new LinkedHashMap<>(row));for(Map<String,Object> row:batch)batches.add(new LinkedHashMap<>(row));}
  State(State old){this(old.sources,old.batches);}
  long available(String identity,String store){long locked=0,publicSource=0;String sku="";for(Map<String,Object> source:sources)if(identity.equals(com.oms.common.util.FulfillmentLineKey.of(source))){sku=s(source,"sku_sn");if(LuckyBagStock.protectedSource(s(source,"source_type"))){if(store.equals(s(source,"store_code")))locked+=n(source,"quantity");}else publicSource+=n(source,"quantity");}long free=0;for(Map<String,Object> batch:batches)if(sku.equals(s(batch,"sku_sn"))&&store.equals(s(batch,"store_code")))free+=n(batch,"available");return locked+Math.min(publicSource,free);}
  long sets(Map<String,Long> coefficients,String store){long sets=Long.MAX_VALUE;for(Map.Entry<String,Long> component:coefficients.entrySet())sets=Math.min(sets,available(component.getKey(),store)/component.getValue());return sets;}
  long coverage(Set<String> identities,String store){long sum=0;for(String identity:identities)sum+=available(identity,store);return sum;}
  List<Map<String,Object>> take(String identity,long quantity,Map<String,Object> store){String code=s(store,"store_code");List<Map<String,Object>> out=new ArrayList<>();long left=quantity;for(String type:Arrays.asList("LOCK","LUCKY","PUBLIC_EXTRA"))for(Map<String,Object> source:sources){if(left==0)break;if(!identity.equals(com.oms.common.util.FulfillmentLineKey.of(source))||!type.equals(s(source,"source_type"))||n(source,"quantity")==0)continue;if(LuckyBagStock.protectedSource(type)){if(!code.equals(s(source,"store_code")))continue;long take=Math.min(left,n(source,"quantity"));out.add(receipt(source,store,n(source,"batch_id"),take));source.put("quantity",n(source,"quantity")-take);left-=take;}else for(Map<String,Object> batch:batches){if(left==0||n(source,"quantity")==0)break;if(!code.equals(s(batch,"store_code"))||!s(source,"sku_sn").equals(s(batch,"sku_sn")))continue;long take=Math.min(left,Math.min(n(source,"quantity"),n(batch,"available")));if(take==0)continue;out.add(receipt(source,store,n(batch,"id"),take));source.put("quantity",n(source,"quantity")-take);batch.put("available",n(batch,"available")-take);left-=take;}}
   require(left==0,"套装组件可用来源发生变化");return out;
  }
 }
 private static Map<String,Object> receipt(Map<String,Object> source,Map<String,Object> store,long batch,long qty){Map<String,Object> row=new LinkedHashMap<>(store);for(String key:Arrays.asList("demand_id","sku_sn","source_type"))row.put(key,source.get(key));row.put("stock_source_id",source.get("id"));row.put("batch_id",batch);row.put("quantity",qty);return row;}
}
